ee:message.ee:set-payload:
%dw 2.0
output application/java
---
{
    "Bills": if(payload.ZFI_PAGOS_LINEA.tables.T_FACTURAS != null) 
    {
        "Bill" : payload.ZFI_PAGOS_LINEA.tables.T_FACTURAS mapObject ((value, key, index) -> {
            (key): value
        })
    }  else null,
    "Result" : {
        "status": if(payload.ZFI_PAGOS_LINEA.tables.T_FACTURAS != null) "PASS" else "FAIL",
        "code" : if(payload.ZFI_PAGOS_LINEA.export.RETURN.TYPE == 'S') 'SUCCESS' else payload.ZFI_PAGOS_LINEA.export.RETURN.CODE,
        "description" : payload.ZFI_PAGOS_LINEA.export.RETURN.MESSAGE
    }
}
